const CACHE='nur-mobile-v18-release';
const SHELL=['./release18.js','./release18.css','./policy-data.js','./privacy.html','./terms.html','./deletion.html','./release17.js','./community.js','./release17.css','./store-copy.js','./mosques.js','./release16.js','./native-store.js','./release16.css','./icons/shams-wordmark.png','./ui-icons.js','./module-access.js','./dua-share.js','./release15.css','./','./index.html','./style.css','./theme.css','./experience.css','./shams.css','./cosmic.css','./modules.css','./premium.css','./premium.js','./social-worship.js','./social-worship.css','./cloud-config.js','./cloud.js','./cloud-admin.js','./cloud.css','./audio/adhan-user.webm','./updates.js','./updates.css','./icons/shams-original.png','./cosmic.js','./companion.js','./learning.js','./quiz-data.js','./names-data.js','./shams.js','./icons/shams-wordmark.svg','./icons/shams-app.png','./icons/prayer-hanafi.png','./icons/prayer-jafari.png','./experience.js','./devotion.js','./guide.js','./compact.js','./i18n.js','./enhancements.js','./mobile.js','./app.js','./manifest.webmanifest','./icons/basira-logo.png','./icons/icon-192.png','./icons/icon-512.png','./icons/icon-maskable-512.png'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL.map(url=>new Request(new URL(url,self.registration.scope).href,{cache:'reload'})))).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('nur-mobile-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const u=new URL(event.request.url);if(event.request.method!=='GET'||u.origin!==self.location.origin)return;if(event.request.mode==='navigate'){event.respondWith(fetch(event.request).catch(()=>caches.match(new URL('./index.html',self.registration.scope).href)));return}if(!SHELL.some(p=>new URL(p,self.registration.scope).pathname===u.pathname))return;event.respondWith(fetch(event.request).then(res=>{if(res.ok){const clone=res.clone();event.waitUntil(caches.open(CACHE).then(c=>c.put(event.request,clone)))}return res}).catch(()=>caches.match(event.request,{ignoreSearch:true})))});
